UPDATE public.blog_posts
SET 
  title = 'Годовой план службы сопровождения: как собрать за август с примерами файлов и таблиц',
  excerpt = 'Пошаговое руководство по составлению годового плана работы службы сопровождения: психолога, логопеда и дефектолога. Образцы документов, графики и информация о социально-психологическом тестировании (СПТ).',
  content = '<h2>Почему август — ключевой месяц для планирования</h2><p>Подготовка годового плана в августе позволяет избежать аврала в сентябре, когда начинается массовый поток детей и документации. Служба сопровождения (ППС) должна войти в учебный год с четким пониманием графиков, зон ответственности и перечнем диагностических мероприятий.</p><h2>Структура годового плана по Приказу № 666</h2><p>Согласно Приказу ДОНМ № 666, план должен охватывать следующие направления:</p><ul><li>Диагностическая работа (скрининги, углубленная диагностика)</li><li>Коррекционно-развивающая работа (индивидуальная и групповая)</li><li>Консультативная деятельность (родители, педагоги)</li><li>Просветительская работа</li><li>Экспертно-методическая работа (участие в ППк, советах профилактики)</li></ul><h2>Социально-психологическое тестирование (СПТ)</h2><p><strong>СПТ — это обязательный этап мониторинга</strong>, направленный на раннее выявление немедицинского потребления ПАВ и оценку факторов риска и защиты. Тестирование проводится ежегодно для обучающихся с 7-го класса (от 13 лет).</p><h3>Этапы СПТ в годовом плане:</h3><ol><li><strong>Сентябрь:</strong> Подготовительный этап. Информирование родителей, сбор согласий (до 15 лет — от родителей, с 15 лет — от обучающихся). Создание комиссии.</li><li><strong>Октябрь:</strong> Проведение тестирования. Важно обеспечить анонимность и конфиденциальность.</li><li><strong>Ноябрь - Декабрь:</strong> Обработка результатов и формирование «групп риска» для дальнейшей профилактической работы.</li></ol><p><em>Совет специалисту:</em> Внесите даты СПТ в календарный график заранее, так как это требует согласования с администрацией и выделения компьютерных классов.</p><h2>Примеры таблиц и графиков</h2><p>Эффективный план — это не только текст, но и визуализация нагрузки. Мы рекомендуем использовать циклограмму, где по вертикали указаны часы, а по горизонтали — дни недели и виды деятельности.</p><table><thead><tr><th>Вид работы</th><th>Периодичность</th><th>Ответственный</th></tr></thead><tbody><tr><td>Скрининг 1-х классов</td><td>Сентябрь - Октябрь</td><td>Психолог, Логопед</td></tr><tr><td>Диагностика СПТ</td><td>Октябрь</td><td>Комиссия, Психолог</td></tr><tr><td>Заседания ППк</td><td>Не реже 1 раза в месяц</td><td>Председатель ППк</td></tr></tbody></tbody></table><h2>Нормативная документация и ссылки</h2><ul><li><a href="https://docs.cntd.ru/document/550882353" target="_blank" rel="noopener">ФЗ-152 «О персональных данных»</a> — основа безопасности при хранении планов.</li><li><a href="https://www.mos.ru/donm/documents/view/217997220/" target="_blank" rel="noopener">Приказ ДОНМ № 666</a> — регламент работы службы.</li><li>Письмо Минпросвещения о проведении СПТ (ежегодное обновление).</li></ul><h2>Автоматизация в universum.</h2><p>Платформа universum. позволяет автоматически генерировать черновик годового плана на основе ваших прошлых отчетов и загруженной нагрузки. Все формы соответствуют требованиям ДОНМ и Минздрава РФ. Вы можете экспортировать план в PDF или Excel за один клик.</p>',
  keywords = ARRAY['годовой план','служба сопровождения','СПТ','планирование','психолог в школе','логопед','дефектолог'],
  reading_minutes = 12,
  updated_at = now()
WHERE id = '668e5228-963f-4493-b488-7ee1922efa91';